{"path":"packages/appboundry-host/test/outbox-outcome.test.ts","content":"/**
 * performOutbox (transactions.ts) when the outcome write fails: the result must match durable
 * state, never report done/failed that was not recorded (issue #99).
 */
import { describe, expect, it } from "vitest";
import { performOutbox, type OutboxRecord } from "../src/transactions.js";

const pending: OutboxRecord = { id: "ob1", requestId: "r1", function: "f", principalId: "dev", effect: { service: "jobs", method: "enqueue", type: "t", payload: {} }, state: "pending", createdAt: 0, updatedAt: 0, attempts: 0 };

/** A one-record store; write n (1 = the claim) throws when `failing(n)`. */
function store(failing: (n: number) => boolean) {
  let version = 1;
  let value: OutboxRecord = { ...pending };
  let writes = 0;
  const db = {
    collection: () => ({ get: async () => ({ ...value, __version: version }), find: async () => [] }),
    transaction: async (request: { operations: Array<{ ifVersion: number; value: OutboxRecord }> }) => {
      const op = request.operations[0]!;
      writes += 1;
      if (failing(writes)) throw new Error("store unavailable");
      if (op.ifVersion !== version) throw new Error("version conflict");
      value = op.value;
      version += 1;
    }
  };
  return { db: db as never, record: () => value };
}

describe("performOutbox outcome write", () => {
  it("does not report done when done could not be recorded", async () => {
    const s = store(n => n >= 2);
    const warnings: string[] = [];
    expect(await performOutbox(s.db, "ob1", async () => ({ jobId: "j" }), m => warnings.push(m))).toBe("skipped");
    expect(s.record().state).toBe("performing");
    expect(warnings.join("\n")).toMatch(/could not record done/);
  });

  it("does not report failed when failed could not be recorded", async () => {
    const s = store(n => n >= 2);
    expect(await performOutbox(s.db, "ob1", async () => { throw new Error("boom"); })).toBe("skipped");
    expect(s.record().state).toBe("performing");
  });

  it("retries a transiently failing outcome write and records it", async () => {
    const s = store(n => n === 2);
    expect(await performOutbox(s.db, "ob1", async () => ({ jobId: "j" }))).toBe("done");
    expect(s.record()).toMatchObject({ state: "done", result: { jobId: "j" }, attempts: 1 });
  });
});
"}

