{"path":"packages/appboundry-host/src/transactions.ts","content":"/**
 * Host interface transactions@1: `db.sequence` and `outbox.stage`, the guest operations behind a
 * producer's transactional sequences and after-commit effects (FeltKit: ctx.db.sequence,
 * ctx.afterCommit). The contract is FeltKit's docs/TRANSACTIONS.md, implemented here on the
 * host's own FeltDB transaction (collections.ts) with host-owned collections:
 *
 *   sequence      per stream (its name): strictly increasing and gapless in commit order, written
 *                 in the mutation's transaction guarded on the version read, so a concurrent
 *                 commit of the same stream refuses the whole transaction (CONFLICT) and a
 *                 failed mutation consumes nothing; independent streams never contend
 *   outbox        one record per effect, committed with the mutation or not at all; performed
 *                 after the commit as the caller (claimed pending → performing, version-checked),
 *                 then done (with its result) or failed (with the error); stale pending and
 *                 performing records are recovered by the worker after a restart; a failed one
 *                 is retried only by an operator. A job or webhook event is created in the same
 *                 FeltDB transaction that records it done (AppPort Services' transaction context,
 *                 @appport/services 0.13.1), so it is created once per committed effect; a
 *                 notification carries the record id as its idempotency key. Creation, not
 *                 delivery: a job's run or a webhook's delivery to its endpoint is the services'
 *                 own (at least once).
 *
 * No second transaction system: the records are extra operations of the mutation's FeltDB
 * transaction.
 */
import { HostError } from "./collections.js";

export const SEQUENCES_COLLECTION = "_appboundry_sequences";
export const OUTBOX_COLLECTION = "_appboundry_outbox";
/** A pending record not performed after this long is recovered (its runtime likely stopped). */
export const OUTBOX_RECOVER_AFTER_MS = 30_000;
/** A record left performing this long (its performer stopped mid-way) is recovered too. */
export const OUTBOX_PERFORMING_STALE_MS = OUTBOX_RECOVER_AFTER_MS * 10;
/** The most re-runs a function's manifest may ask for on sequence contention. */
export const MAX_SEQUENCE_RETRIES = 10;
/** How many times an effect's outcome (done or failed) is written while its claim is still current. */
const OUTCOME_WRITE_ATTEMPTS = 3;

const SEQUENCE_NAME = /^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$/;
const RECORD_ID = /^[A-Za-z0-9._-]{1,128}$/;

/**
 * The record id a stream is stored under: the name itself when it is a valid FeltDB id, else "_"
 * + the name with "." written ".d" and ":" written ".c" (injective, never equal to a name).
 */
export function sequenceRecordId(name: unknown): string {
  if (typeof name !== "string" || !SEQUENCE_NAME.test(name)) {
    throw new HostError("INVALID_ARGUMENT", `Sequence name ${JSON.stringify(name)} must be 1-128 letters, digits, "_", ".", ":" or "-", starting with a letter or digit.`);
  }
  if (RECORD_ID.test(name)) return name;
  const id = `_${name.replace(/\./g, ".d").replace(/:/g, ".c")}`;
  if (!RECORD_ID.test(id)) throw new HostError("INVALID_ARGUMENT", `Sequence name ${JSON.stringify(name)} is too long to store (${id.length} characters encoded, at most 128).`);
  return id;
}

/** The sequences one mutation drew from, and the guarded writes that advance them. */
export class SequenceAllocations {
  readonly #streams = new Map<string, { id: string; version: number | null; committed: number; next: number }>();

  async next(name: unknown, read: (id: string) => Promise<{ value?: unknown; __version: number } | null>): Promise<number> {
    const key = String(name);
    let stream = this.#streams.get(key);
    if (!stream) {
      const id = sequenceRecordId(name);
      const record = await read(id);
      const committed = typeof record?.value === "number" ? record.value : 0;
      stream = { id, version: record ? record.__version : null, committed, next: committed };
      this.#streams.set(key, stream);
    }
    stream.next += 1;
    return stream.next;
  }

  operations(transactionId: string): Array<Record<string, unknown>> {
    const out: Array<Record<string, unknown>> = [];
    for (const [name, s] of this.#streams) {
      if (s.next === s.committed) continue;
      const value = { id: s.id, name, value: s.next, transactionId };
      out.push(s.version === null ? { collection: SEQUENCES_COLLECTION, id: s.id, requireAbsent: true, value } : { collection: SEQUENCES_COLLECTION, id: s.id, ifVersion: s.version, value });
    }
    return out;
  }
}

export type OutboxEffect =
  | { service: "notifications"; method: "send"; input: Record<string, unknown> & { recipient: string; type: string; title: string; idempotencyKey?: string } }
  | { service: "webhooks"; method: "emit"; type: string; payload: Record<string, unknown> }
  | { service: "jobs"; method: "enqueue"; type: string; payload: Record<string, unknown>; options?: { runAt?: string; maxAttempts?: number } };

export interface OutboxRecord {
  id: string;
  requestId: string;
  function: string;
  principalId: string;
  /** The tenant the caller worked in (tenancy@1): a recovered effect is performed there, through the live membership only. */
  tenantId?: string;
  effect: OutboxEffect;
  state: "pending" | "performing" | "done" | "failed";
  createdAt: number;
  updatedAt: number;
  attempts: number;
  error?: { code: string; message: string };
  result?: Record<string, unknown>;
  retriedBy?: string;
  __version?: number;
}

const isObject = (v: unknown): v is Record<string, unknown> => typeof v === "object" && v !== null && !Array.isArray(v);
const text = (v: unknown) => typeof v === "string" && v.trim().length > 0;

/**
 * The outbox records a guest staged (`outbox.stage { effects: [{ id, effect }] }`), validated: the
 * effect's shape, and its service enabled in the manifest. Caller, request and function come from
 * the call, never from the guest.
 */
export function stagedRecords(input: unknown, call: { fn: string; principalId: string | null; tenantId?: string | null; requestId: string; services: readonly string[] }, now = Date.now()): OutboxRecord[] {
  const effects = isObject(input) && Array.isArray(input.effects) ? input.effects : null;
  if (!effects) throw new HostError("INVALID_ARGUMENT", "outbox.stage needs { effects: [{ id, effect }] }.");
  if (!call.principalId) throw new HostError("UNAUTHORIZED", "Authentication is required to use services");
  return effects.map((staged: unknown) => {
    const id = isObject(staged) ? staged.id : undefined;
    const effect = isObject(staged) ? staged.effect : undefined;
    if (typeof id !== "string" || !RECORD_ID.test(id)) throw new HostError("INVALID_ARGUMENT", "An outbox record needs an id of 1-128 letters, digits, \".\", \"_\" or \"-\".");
    if (!isObject(effect)) throw new HostError("INVALID_ARGUMENT", "An after-commit effect is notifications.send, webhooks.emit or jobs.enqueue.");
    let valid: OutboxEffect;
    if (effect.service === "notifications" && effect.method === "send" && isObject(effect.input) && text(effect.input.recipient) && text(effect.input.type) && text(effect.input.title)) {
      valid = { service: "notifications", method: "send", input: effect.input as OutboxEffect & never };
    } else if (effect.service === "webhooks" && effect.method === "emit" && text(effect.type) && isObject(effect.payload ?? {})) {
      valid = { service: "webhooks", method: "emit", type: effect.type as string, payload: (effect.payload ?? {}) as Record<string, unknown> };
    } else if (effect.service === "jobs" && effect.method === "enqueue" && text(effect.type) && isObject(effect.payload ?? {}) && (effect.options === undefined || isObject(effect.options))) {
      valid = { service: "jobs", method: "enqueue", type: effect.type as string, payload: (effect.payload ?? {}) as Record<string, unknown>, ...(effect.options ? { options: effect.options as { runAt?: string; maxAttempts?: number } } : {}) };
    } else {
      throw new HostError("INVALID_ARGUMENT", "An after-commit effect is notifications.send { recipient, type, title }, webhooks.emit { type, payload } or jobs.enqueue { type, payload, options? }.");
    }
    if (!call.services.includes(valid.service)) {
      throw new HostError("CONFIGURATION", `The ${valid.service[0]!.toUpperCase()}${valid.service.slice(1)} service is not enabled.`);
    }
    return { id, requestId: call.requestId, function: call.fn, principalId: call.principalId!, ...(call.tenantId ? { tenantId: call.tenantId } : {}), effect: JSON.parse(JSON.stringify(valid)) as OutboxEffect, state: "pending", createdAt: now, updatedAt: now, attempts: 0 };
  });
}

export function isRecoverable(record: Pick<OutboxRecord, "state" | "updatedAt">, now: number): boolean {
  return (record.state === "pending" && now - record.updatedAt >= OUTBOX_RECOVER_AFTER_MS) || (record.state === "performing" && now - record.updatedAt >= OUTBOX_PERFORMING_STALE_MS);
}

function strip(record: OutboxRecord): OutboxRecord {
  const { __version: _v, ...rest } = record;
  return rest;
}

export function retried(record: OutboxRecord, by: string, now = Date.now()): OutboxRecord {
  if (record.state !== "failed") throw new HostError("FAILED_PRECONDITION", `After-commit effect ${record.id} is ${record.state}; only a failed effect can be retried.`);
  return { ...strip(record), state: "pending", updatedAt: now, retriedBy: by };
}

type Store = { collection(name: string): { get(id: string): Promise<unknown>; find(filter: Record<string, unknown>): Promise<unknown[]> }; transaction(request: never): Promise<unknown> };

/** Write `value` only if the record is still at `version` (throws otherwise; nothing written). */
async function put(db: Store, id: string, version: number, value: OutboxRecord): Promise<void> {
  await db.transaction({ operations: [{ collection: OUTBOX_COLLECTION, id, ifVersion: version, value: strip(value) }] } as never);
}

/**
 * The write that records `claim` done with `result`, guarded on the claim's version: an effect
 * that commits it in its own transaction (a job, webhook deliveries) is created exactly when the
 * record says done, and a stale claim creates nothing.
 */
export function completion(claim: OutboxRecord & { __version: number }, result: Record<string, unknown>): Record<string, unknown> {
  const { error: _e, ...rest } = strip(claim);
  return { collection: OUTBOX_COLLECTION, id: claim.id, expectedVersion: claim.__version, value: { ...rest, state: "done", updatedAt: Date.now(), ...(Object.keys(result).length ? { result } : {}) } };
}

/**
 * Perform one record: claim it (version-checked, so two performers never both perform it),
 * perform, record done with its result or failed with the error. `perform` may instead commit
 * the done write itself, in the transaction that creates the effect (`complete(result)` gives it);
 * then nothing more is written. Never throws: the mutation has committed. `done` and `failed` are
 * returned only once recorded. `skipped`: gone, settled, claimed by another performer, or its
 * outcome could not be recorded (retried while the claim is current; the record stays as stored).
 */
export async function performOutbox(db: Store, id: string, perform: (record: OutboxRecord, complete: (result: Record<string, unknown>) => Record<string, unknown>) => Promise<Record<string, unknown>>, warn: (message: string) => void = () => {}): Promise<"done" | "failed" | "skipped"> {
  const get = async () => ((await db.collection(OUTBOX_COLLECTION).get(id).catch(() => null)) as (OutboxRecord & { __version: number }) | null) ?? null;
  const current = await get();
  if (!current || current.state === "done" || current.state === "failed") return "skipped";
  try {
    await put(db, id, current.__version, { ...current, state: "performing", attempts: (current.attempts ?? 0) + 1, updatedAt: Date.now() });
  } catch {
    return "skipped";
  }
  const claim = await get();
  if (!claim || claim.state !== "performing") return "skipped";
  let next: OutboxRecord;
  let completed = false;
  const complete = (result: Record<string, unknown>) => {
    completed = true;
    return completion(claim, result);
  };
  try {
    const result = await perform(claim, complete);
    // Committed with the effect: done is already recorded.
    if (completed) return "done";
    const { error: _e, ...rest } = claim;
    next = { ...rest, state: "done", updatedAt: Date.now(), ...(Object.keys(result).length ? { result } : {}) };
  } catch (error) {
    const e = error as { code?: string; message?: string };
    next = { ...claim, state: "failed", updatedAt: Date.now(), error: { code: e?.code ?? "INTERNAL", message: e?.message ?? String(error) } };
    warn(`after-commit ${claim.effect.service}.${claim.effect.method} from ${claim.function} failed: ${next.error!.message}`);
  }
  for (let attempt = 1; ; attempt++) {
    try {
      await put(db, id, claim.__version, next);
      return next.state as "done" | "failed";
    } catch (error) {
      // Retry only while the claim is still the stored version; otherwise report what is durable: not this outcome.
      const stored = await get();
      if (!stored || stored.__version !== claim.__version || attempt >= OUTCOME_WRITE_ATTEMPTS) {
        warn(`after-commit ${id}: could not record ${next.state}: ${(error as Error).message}`);
        return "skipped";
      }
    }
  }
}

/** The service call an effect is. */
export function serviceCall(record: OutboxRecord): { service: string; method: string; input: Record<string, unknown> } {
  const effect = record.effect;
  if (effect.service === "notifications") return { service: "notifications", method: "send", input: { ...effect.input, idempotencyKey: effect.input.idempotencyKey ?? record.id } };
  if (effect.service === "jobs") return { service: "jobs", method: "enqueue", input: { type: effect.type, payload: effect.payload, ...(effect.options ? { options: effect.options } : {}) } };
  return { service: "webhooks", method: "emit", input: { type: effect.type, payload: effect.payload } };
}

/** What an effect produced, as recorded on its outbox record. */
export function effectResult(record: OutboxRecord, value: unknown): Record<string, unknown> {
  const v = (value ?? {}) as Record<string, unknown>;
  if (record.effect.service === "notifications") return typeof v.id === "string" ? { notificationId: v.id } : {};
  if (record.effect.service === "jobs") return typeof v.id === "string" ? { jobId: v.id } : {};
  return { deliveries: typeof v.deliveries === "number" ? v.deliveries : Array.isArray(value) ? value.length : 0 };
}

/** The retry policy a manifest function entry may carry. */
export function retryPolicy(value: unknown, kind: string): { sequenceConflicts: number } | undefined {
  if (value === undefined) return undefined;
  const n = isObject(value) ? value.sequenceConflicts : undefined;
  if (kind !== "mutation" || !Number.isInteger(n) || (n as number) < 1 || (n as number) > MAX_SEQUENCE_RETRIES) {
    throw new Error(`retry must be { sequenceConflicts: 1-${MAX_SEQUENCE_RETRIES} } on a mutation`);
  }
  return { sequenceConflicts: n as number };
}

/** After-commit effects in `db`, newest first (optionally only one state). */
export async function listOutbox(db: { collection(name: string): { find(filter: Record<string, unknown>): Promise<unknown[]> } }, filter: { state?: string; limit?: number } = {}): Promise<OutboxRecord[]> {
  if (filter.state !== undefined && !["pending", "performing", "done", "failed"].includes(filter.state)) throw new HostError("INVALID_ARGUMENT", "state is pending, performing, done or failed.");
  const rows = (await db.collection(OUTBOX_COLLECTION).find(filter.state ? { state: filter.state } : {})) as Array<OutboxRecord & { __version?: number }>;
  return rows.map(r => strip(r)).sort((a, b) => b.createdAt - a.createdAt).slice(0, Math.min(Math.max(Number(filter.limit) || 100, 1), 1000));
}

/** Move a failed record back to pending (an operator's retry); a running host then performs it. */
export async function retryOutboxRecord(db: Store, id: unknown, by: string): Promise<OutboxRecord> {
  if (typeof id !== "string" || !id) throw new HostError("INVALID_ARGUMENT", "Name the after-commit effect to retry (see `appboundry admin outbox list --status failed`).");
  const record = (await db.collection(OUTBOX_COLLECTION).get(id).catch(() => null)) as (OutboxRecord & { __version: number }) | null;
  if (!record) throw new HostError("NOT_FOUND", `No after-commit effect ${id}.`);
  const next = retried(record, by);
  try {
    await put(db, id, record.__version, next);
  } catch {
    throw new HostError("CONFLICT", `After-commit effect ${id} changed while it was being retried. Nothing was changed; read it again.`);
  }
  return next;
}
"}

